INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Save the Sharks!', 'Sharks are in danger. Every year, millions of sharks are killed for their fins. This is very cruel. Fishermen catch the sharks, cut off their fins, and throw the sharks back into the sea. Without their fins, the sharks cannot swim, and they soon die. Sharks are at the top of the food chain. They help keep the ocean''s ecosystem healthy. If all the sharks disappear, the whole ocean will be in danger. Some people eat shark fins because they think they are good for health. But no scientific studies have shown this. We should all help save the sharks. We can refuse to eat shark fins and ask others to do the same.', '说明文', 114, '[{"q": "Why are sharks in danger?", "answer": "A", "options": ["They are killed for their fins.", "The sea is too warm.", "They are too slow.", "They have no food."], "explanation": "原文:killed for their fins"}, {"q": "What happens to sharks without their fins?", "answer": "B", "options": ["They swim faster.", "They cannot swim and soon die.", "They become healthy.", "They grow new fins."], "explanation": "原文:cannot swim, and they soon die"}, {"q": "Where are sharks in the food chain?", "answer": "A", "options": ["At the top.", "At the bottom.", "In the middle.", "Outside it."], "explanation": "原文:at the top of the food chain"}, {"q": "Do scientific studies show shark fins are good for health?", "answer": "B", "options": ["Only a few.", "No.", "Sometimes.", "Yes."], "explanation": "原文:no scientific studies have shown this"}, {"q": "What should we do to help?", "answer": "C", "options": ["Eat more fins.", "Do nothing.", "Refuse to eat shark fins.", "Catch more sharks."], "explanation": "原文:refuse to eat shark fins"}]'::jsonb, '[{"word": "shark", "cn": "鲨鱼"}, {"word": "cruel", "cn": "残酷的"}, {"word": "ecosystem", "cn": "生态系统"}]'::jsonb, 3, '9', 'U13');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Rethink, Reuse, Recycle', 'We all create waste every day. But there are three simple ways to help the earth: rethink, reuse, and recycle. First, rethink. Before you buy something, ask if you really need it. The more we buy, the more waste we make. Second, reuse. Many things can be used again. You can use a glass bottle to hold water, or turn an old box into a useful container. Third, recycle. Paper, glass, and metal can all be recycled. They can be made into new things. If we all take action, we can make a big difference. Saving the earth is not hard. It just takes a little thought and effort from everyone.', '说明文', 111, '[{"q": "How many ways are there to help the earth?", "answer": "C", "options": ["Two.", "Four.", "Three.", "Five."], "explanation": "原文:three simple ways"}, {"q": "What should you do before you buy something?", "answer": "B", "options": ["Pay more.", "Ask if you really need it.", "Buy two.", "Throw it away."], "explanation": "原文:ask if you really need it"}, {"q": "What can you do with a glass bottle?", "answer": "D", "options": ["Bury it.", "Throw it away.", "Burn it.", "Use it to hold water."], "explanation": "原文:use a glass bottle to hold water"}, {"q": "What can be recycled?", "answer": "D", "options": ["Nothing.", "Only paper.", "Only food.", "Paper, glass, and metal."], "explanation": "原文:Paper, glass, and metal can all be recycled"}, {"q": "Is saving the earth hard?", "answer": "C", "options": ["Very hard.", "Yes.", "No.", "Impossible."], "explanation": "原文:not hard"}]'::jsonb, '[{"word": "recycle", "cn": "回收利用"}, {"word": "bottle", "cn": "瓶子"}, {"word": "metal", "cn": "金属"}]'::jsonb, 3, '9', 'U13');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'The Bottle House', 'In a small town, there was a man named Mr. Lee. He loved to reuse old things. One day, he had an idea. He decided to build a house using old glass bottles. People thought he was crazy. "You can''t build a house from rubbish!" they said. But Mr. Lee did not give up. He collected thousands of bottles that people had thrown away. He put them to good use. After two years, the house was finished. It was beautiful and colorful. The sun shone through the bottles like a rainbow. Now, people come from far away to see the bottle house. Mr. Lee showed everyone that old things can become a work of art.', '记叙文', 115, '[{"q": "What did Mr. Lee love to do?", "answer": "B", "options": ["Throw things away.", "Reuse old things.", "Sell bottles.", "Buy new things."], "explanation": "原文:loved to reuse old things"}, {"q": "What did he decide to build?", "answer": "B", "options": ["A school.", "A house from old glass bottles.", "A boat.", "A car."], "explanation": "原文:build a house using old glass bottles"}, {"q": "What did people think at first?", "answer": "C", "options": ["He was rich.", "He was kind.", "He was crazy.", "He was clever."], "explanation": "原文:thought he was crazy"}, {"q": "How long did it take to finish?", "answer": "A", "options": ["Two years.", "Two days.", "Two weeks.", "Two months."], "explanation": "原文:After two years"}, {"q": "What did Mr. Lee show everyone?", "answer": "C", "options": ["Rubbish is bad.", "Bottles are useless.", "Old things can become a work of art.", "Houses are cheap."], "explanation": "原文:old things can become a work of art"}]'::jsonb, '[{"word": "bottle", "cn": "瓶子"}, {"word": "reuse", "cn": "再利用"}, {"word": "work", "cn": "作品"}]'::jsonb, 3, '9', 'U13');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Plastic or Paper?', 'When we go shopping, we often have to choose between plastic bags and paper bags. Which is better for the earth? Plastic bags are cheap and strong. But they are very harmful to the environment. They do not break down for hundreds of years. Many plastic bags end up in the sea, where they hurt animals. Paper bags break down more easily, but making them uses many trees. So what is the best choice? The answer is simple: use a reusable bag! A reusable bag can be used many times. It saves money and helps the earth. Next time you go shopping, remember to bring your own bag.', '议论文', 108, '[{"q": "What do we often choose between when shopping?", "answer": "C", "options": ["Food and drink.", "Books and pens.", "Plastic bags and paper bags.", "Cars and bikes."], "explanation": "原文:between plastic bags and paper bags"}, {"q": "Why are plastic bags harmful?", "answer": "C", "options": ["They are weak.", "They are heavy.", "They do not break down for hundreds of years.", "They are expensive."], "explanation": "原文:do not break down for hundreds of years"}, {"q": "What problem do paper bags have?", "answer": "D", "options": ["They are too strong.", "They cost too much.", "They never break down.", "Making them uses many trees."], "explanation": "原文:making them uses many trees"}, {"q": "What is the best choice?", "answer": "A", "options": ["A reusable bag.", "No bag.", "A plastic bag.", "A paper bag."], "explanation": "原文:use a reusable bag"}, {"q": "What should you do next time you shop?", "answer": "B", "options": ["Buy plastic.", "Bring your own bag.", "Use both.", "Buy paper."], "explanation": "原文:bring your own bag"}]'::jsonb, '[{"word": "plastic", "cn": "塑料的"}, {"word": "harmful", "cn": "有害的"}, {"word": "reusable", "cn": "可重复使用的"}]'::jsonb, 3, '9', 'U13');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Small Actions, Big Difference', 'Saving the earth is not only the job of governments. Each of us can help, too. There are many small actions we can take. We can turn off the lights when we leave a room. This saves energy. We can ride bikes or take public transportation instead of driving cars. This makes the air cleaner. We can use less paper and recycle what we use. This saves trees. We can carry a reusable water bottle instead of buying plastic ones. We can also tell our friends and family to do the same. These small actions may seem unimportant, but together they can make a big difference. The earth is our home, and we must take care of it.', '说明文', 118, '[{"q": "Whose job is saving the earth?", "answer": "C", "options": ["Only scientists''.", "Only governments''.", "Everyone''s, not only governments''.", "Only teachers''."], "explanation": "原文:not only the job of governments"}, {"q": "What does turning off lights save?", "answer": "B", "options": ["Money only.", "Energy.", "Water.", "Trees."], "explanation": "原文:This saves energy"}, {"q": "What makes the air cleaner?", "answer": "A", "options": ["Riding bikes or taking public transportation.", "Burning coal.", "Using plastic.", "Driving more."], "explanation": "原文:ride bikes or take public transportation"}, {"q": "What does using less paper save?", "answer": "D", "options": ["Time.", "Water.", "Energy.", "Trees."], "explanation": "原文:This saves trees"}, {"q": "What can small actions do together?", "answer": "D", "options": ["Cause harm.", "Nothing.", "Waste time.", "Make a big difference."], "explanation": "原文:make a big difference"}]'::jsonb, '[{"word": "transportation", "cn": "运输;交通"}, {"word": "recycle", "cn": "回收"}, {"word": "reusable", "cn": "可重复使用的"}]'::jsonb, 3, '9', 'U13');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Green School Notice', 'GREEN SCHOOL WEEK! Let''s work together to protect our environment. Here is how you can help. MONDAY: Turn off lights and computers when you leave the classroom. Save energy! TUESDAY: Bring a reusable water bottle. Do not use plastic ones. WEDNESDAY: Use both sides of your paper. Save trees! THURSDAY: Put rubbish in the right bins. We will recycle paper, glass, and metal. FRIDAY: Walk or ride a bike to school if you can. Remember, the earth is our home. Every small action counts. Let''s take action together and make our school a greener place. Thank you for your help!', '应用文', 100, '[{"q": "What is the notice about?", "answer": "A", "options": ["Green School Week.", "A party week.", "A sports week.", "An exam week."], "explanation": "原文:GREEN SCHOOL WEEK"}, {"q": "What should you do on Monday?", "answer": "D", "options": ["Ride a bike.", "Bring a bottle.", "Use both sides of paper.", "Turn off lights and computers."], "explanation": "原文:Monday: Turn off lights and computers"}, {"q": "What should you bring on Tuesday?", "answer": "A", "options": ["A reusable water bottle.", "A book.", "A paper bag.", "A plastic bottle."], "explanation": "原文:Bring a reusable water bottle"}, {"q": "What will be recycled on Thursday?", "answer": "A", "options": ["Paper, glass, and metal.", "Only food.", "Only paper.", "Nothing."], "explanation": "原文:recycle paper, glass, and metal"}, {"q": "What counts according to the notice?", "answer": "D", "options": ["Only big actions.", "Only teachers.", "Only money.", "Every small action."], "explanation": "原文:Every small action counts"}]'::jsonb, '[{"word": "recycle", "cn": "回收"}, {"word": "reusable", "cn": "可重复使用的"}, {"word": "bin", "cn": "垃圾箱"}]'::jsonb, 3, '9', 'U13');
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U13', 'Save the Sharks', 'Sharks are in (1)____. Every year, millions of sharks are (2)____ for their fins. This is very (3)____. Fishermen cut off their fins and (4)____ the sharks back into the sea. Without their fins, the sharks cannot (5)____ and soon die. Sharks are at the top of the food (6)____. They keep the ocean''s ecosystem (7)____. If all the sharks (8)____, the ocean will be in danger. We (9)____ all help save the sharks. We can (10)____ to eat shark fins.', 81, 3, '[{"q": "1", "answer": "D", "options": ["price", "game", "color", "danger"], "explanation": "危险 in danger"}, {"q": "2", "answer": "C", "options": ["kills", "killing", "killed", "kill"], "explanation": "被杀 are killed"}, {"q": "3", "answer": "B", "options": ["kind", "cruel", "good", "nice"], "explanation": "残酷 cruel"}, {"q": "4", "answer": "D", "options": ["build", "lose", "break", "throw"], "explanation": "扔 throw"}, {"q": "5", "answer": "C", "options": ["build", "break", "swim", "lose"], "explanation": "游泳 swim"}, {"q": "6", "answer": "A", "options": ["chain", "game", "price", "color"], "explanation": "链 food chain"}, {"q": "7", "answer": "B", "options": ["sick", "healthy", "tired", "weak"], "explanation": "健康 healthy"}, {"q": "8", "answer": "A", "options": ["disappear", "break", "lose", "build"], "explanation": "消失 disappear"}, {"q": "9", "answer": "B", "options": ["must to", "should", "ought", "shall"], "explanation": "情态 should"}, {"q": "10", "answer": "A", "options": ["refuse", "build", "lose", "break"], "explanation": "拒绝 refuse"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U13', 'The Three R''s', 'We all create (1)____ every day. But there are three ways to help the (2)____: rethink, reuse, and recycle. First, (3)____. Before you buy something, ask if you really (4)____ it. Second, reuse. Many things can be (5)____ again. You can use a glass (6)____ to hold water. Third, recycle. Paper, glass, and (7)____ can all be recycled into new things. If we all take (8)____, we can make a big (9)____. Saving the earth is not (10)____. It just takes a little effort.', 84, 3, '[{"q": "1", "answer": "C", "options": ["price", "color", "waste", "game"], "explanation": "垃圾 waste"}, {"q": "2", "answer": "B", "options": ["price", "earth", "color", "game"], "explanation": "地球 earth"}, {"q": "3", "answer": "A", "options": ["rethink", "build", "break", "lose"], "explanation": "重新思考 rethink"}, {"q": "4", "answer": "A", "options": ["need", "lose", "build", "break"], "explanation": "需要 need"}, {"q": "5", "answer": "C", "options": ["use", "uses", "used", "using"], "explanation": "被使用 be used"}, {"q": "6", "answer": "B", "options": ["color", "bottle", "price", "game"], "explanation": "瓶子 bottle"}, {"q": "7", "answer": "D", "options": ["color", "game", "price", "metal"], "explanation": "金属 metal"}, {"q": "8", "answer": "D", "options": ["color", "game", "price", "action"], "explanation": "行动 take action"}, {"q": "9", "answer": "A", "options": ["difference", "color", "game", "price"], "explanation": "差别 difference"}, {"q": "10", "answer": "B", "options": ["good", "hard", "easy", "kind"], "explanation": "难 hard"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U13', 'The Bottle House', 'In a small town, there was a man named Mr. Lee. He loved to (1)____ old things. One day, he had an (2)____. He decided to build a house using old glass (3)____. People thought he was (4)____. But Mr. Lee did not give (5)____. He collected thousands of bottles that people had (6)____ away. He put them to good (7)____. After two years, the house was (8)____. It was beautiful and colorful. Now people come to see it. Mr. Lee showed everyone that old things can become a (9)____ of art. His story is a real (10)____.', 98, 3, '[{"q": "1", "answer": "B", "options": ["lose", "reuse", "break", "build"], "explanation": "再利用 reuse"}, {"q": "2", "answer": "A", "options": ["idea", "game", "color", "price"], "explanation": "主意 idea"}, {"q": "3", "answer": "B", "options": ["prices", "bottles", "games", "colors"], "explanation": "瓶子 bottles"}, {"q": "4", "answer": "C", "options": ["kind", "good", "crazy", "nice"], "explanation": "疯狂 crazy"}, {"q": "5", "answer": "D", "options": ["in", "off", "on", "up"], "explanation": "放弃 give up"}, {"q": "6", "answer": "D", "options": ["throws", "throwing", "throw", "thrown"], "explanation": "扔掉 had thrown"}, {"q": "7", "answer": "B", "options": ["color", "use", "game", "price"], "explanation": "用途 good use"}, {"q": "8", "answer": "C", "options": ["finishing", "finish", "finished", "finishes"], "explanation": "完成 was finished"}, {"q": "9", "answer": "A", "options": ["work", "price", "game", "color"], "explanation": "作品 work of art"}, {"q": "10", "answer": "A", "options": ["inspiration", "game", "color", "price"], "explanation": "灵感 inspiration"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U13', 'Plastic or Paper?', 'When we go shopping, we often choose between (1)____ bags and paper bags. Which is better for the (2)____? Plastic bags are cheap and strong. But they are very (3)____ to the environment. They do not break (4)____ for hundreds of years. Many end up in the (5)____, where they hurt animals. Paper bags break down more (6)____, but making them uses many (7)____. So what is the best (8)____? Use a (9)____ bag! It can be used many times. Next time you shop, remember to (10)____ your own bag.', 90, 3, '[{"q": "1", "answer": "A", "options": ["plastic", "color", "game", "price"], "explanation": "塑料 plastic"}, {"q": "2", "answer": "B", "options": ["price", "earth", "color", "game"], "explanation": "地球 earth"}, {"q": "3", "answer": "C", "options": ["helpful", "good", "harmful", "useful"], "explanation": "有害 harmful"}, {"q": "4", "answer": "B", "options": ["on", "down", "in", "off"], "explanation": "分解 break down"}, {"q": "5", "answer": "D", "options": ["price", "game", "color", "sea"], "explanation": "海洋 sea"}, {"q": "6", "answer": "C", "options": ["late", "slow", "easily", "hard"], "explanation": "容易 easily"}, {"q": "7", "answer": "A", "options": ["trees", "prices", "colors", "games"], "explanation": "树 trees"}, {"q": "8", "answer": "A", "options": ["choice", "game", "price", "color"], "explanation": "选择 choice"}, {"q": "9", "answer": "B", "options": ["paper", "reusable", "new", "plastic"], "explanation": "可重复使用 reusable"}, {"q": "10", "answer": "D", "options": ["break", "lose", "build", "bring"], "explanation": "带 bring"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U13', 'Small Actions', 'Saving the earth is not only the job of (1)____. Each of us can help, too. We can turn (2)____ the lights when we leave a room. This (3)____ energy. We can ride bikes or take public (4)____ instead of driving. This makes the air (5)____. We can use (6)____ paper and recycle what we use. This saves (7)____. We can carry a reusable water (8)____ instead of buying plastic ones. These small actions may seem (9)____, but together they make a big (10)____. The earth is our home, and we must take care of it.', 96, 3, '[{"q": "1", "answer": "A", "options": ["governments", "games", "colors", "prices"], "explanation": "政府 governments"}, {"q": "2", "answer": "B", "options": ["up", "off", "in", "on"], "explanation": "关掉 turn off"}, {"q": "3", "answer": "A", "options": ["saves", "build", "lose", "break"], "explanation": "节省 saves"}, {"q": "4", "answer": "D", "options": ["color", "game", "price", "transportation"], "explanation": "交通 transportation"}, {"q": "5", "answer": "C", "options": ["dirtier", "worse", "cleaner", "older"], "explanation": "更干净 cleaner"}, {"q": "6", "answer": "B", "options": ["much", "less", "many", "more"], "explanation": "更少 less"}, {"q": "7", "answer": "B", "options": ["games", "trees", "prices", "colors"], "explanation": "树 trees"}, {"q": "8", "answer": "C", "options": ["price", "game", "bottle", "color"], "explanation": "瓶子 bottle"}, {"q": "9", "answer": "A", "options": ["unimportant", "useful", "important", "good"], "explanation": "不重要 unimportant"}, {"q": "10", "answer": "D", "options": ["game", "price", "color", "difference"], "explanation": "差别 difference"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U13', 'Green School Week', 'Green School Week is here! Let''s work (1)____ to protect our environment. On Monday, turn (2)____ lights and computers when you leave. Save (3)____! On Tuesday, bring a (4)____ water bottle. Do not use (5)____ ones. On Wednesday, use both (6)____ of your paper. Save trees! On Thursday, put rubbish in the right (7)____. We will (8)____ paper, glass, and metal. On Friday, walk or ride a bike to school. Remember, the earth is our (9)____. Every small action (10)____. Let''s make our school a greener place!', 87, 3, '[{"q": "1", "answer": "C", "options": ["away", "apart", "together", "alone"], "explanation": "一起 together"}, {"q": "2", "answer": "B", "options": ["up", "off", "on", "in"], "explanation": "关掉 turn off"}, {"q": "3", "answer": "A", "options": ["energy", "game", "price", "color"], "explanation": "能源 energy"}, {"q": "4", "answer": "C", "options": ["new", "plastic", "reusable", "paper"], "explanation": "可重复 reusable"}, {"q": "5", "answer": "A", "options": ["plastic", "price", "color", "game"], "explanation": "塑料 plastic"}, {"q": "6", "answer": "A", "options": ["sides", "games", "prices", "colors"], "explanation": "面 both sides"}, {"q": "7", "answer": "D", "options": ["games", "colors", "prices", "bins"], "explanation": "垃圾箱 bins"}, {"q": "8", "answer": "D", "options": ["build", "break", "lose", "recycle"], "explanation": "回收 recycle"}, {"q": "9", "answer": "B", "options": ["price", "home", "color", "game"], "explanation": "家 home"}, {"q": "10", "answer": "B", "options": ["lose", "counts", "build", "break"], "explanation": "重要 counts"}]'::jsonb, 6);
