INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U13 听力·短文 Green School Week', '九年级 Unit13 听力·环境保护/综合复习', 2, 'This week is Green School Week.
INSERT INTO public.junior_writing_prompts (id, grade, topic, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, difficulty, title_en, high_sentences, error_pairs, paragraph_template, volume, unit) SELECT gen_random_uuid(), 9, 'Saving Our Environment', '写一篇关于保护环境的短文。说明你们当地的一个环境问题,并提出你的建议(用should/can表达,用被动语态描述问题)。60词左右。', 'Write a short passage on the topic: "Saving Our Environment".', '["你们当地的一个环境问题(用被动语态:is polluted/are cut down)", "为什么这是个问题", "你的建议(用should/can:We should.../We can...)", "呼吁大家一起行动"]'::jsonb, 70, 100, 'The river near my home is badly polluted. Litter is thrown into it every day, and the water used to be clean. This is harmful to fish and people. We should take action to save our environment. We can stop throwing rubbish into the river. We can also recycle paper, glass, and metal instead of throwing them away. If we all do our part, we can make a big difference. The earth is our home, and we must protect it.', 'content:含环境问题/危害/建议/呼吁(4分)；language:正确使用被动语态及should/can(3分)；structure:论证清楚、衔接得当(2分)；wordcount:词数达标、书写规范(1分)', 3, 'Saving Our Environment', '["The river/air is badly polluted.", "We should ...", "We can ...", "Trees are being cut down.", "take action", "reduce, reuse, recycle", "The earth is our home."]'::jsonb, '[]'::jsonb, '要点:你们当地的一个环境问题(用被动语态:is polluted/are cut down)；为什么这是个问题；你的建议(用should/can:We should.../We can...)；呼吁大家一起行动', '9', 'U13' WHERE NOT EXISTS (SELECT 1 FROM public.junior_writing_prompts WHERE volume='9' AND unit='U13' AND topic='Saving Our Environment');
